using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Azure.ResourceManager
{
    internal sealed class ResponseErrorConverter : JsonConverter<ResponseError>
    {
        public override ResponseError Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            using var document = JsonDocument.ParseValue(ref reader);
            var element = document.RootElement;

            string code = null;
            string message = null;
            string target = null;
            ResponseInnerError innerError = null;
            List<ResponseError> details = null;

            if (element.TryGetProperty("error", out var errorElement))
            {
                element = errorElement;
            }

            if (element.TryGetProperty("code", out var codeProp))
            {
                code = codeProp.GetString();
            }
            if (element.TryGetProperty("message", out var messageProp))
            {
                message = messageProp.GetString();
            }
            if (element.TryGetProperty("target", out var targetProp))
            {
                target = targetProp.GetString();
            }
            if (element.TryGetProperty("details", out var detailsProp) && detailsProp.ValueKind == JsonValueKind.Array)
            {
                details = new List<ResponseError>();
                foreach (var item in detailsProp.EnumerateArray())
                {
                    var detailJson = item.GetRawText();
                    details.Add(JsonSerializer.Deserialize(detailJson, ResourceManagerJsonSerializerContext.Default.ResponseError));
                }
            }

            return new ResponseError(code, message, target, default, innerError, details);
        }

        public override void Write(Utf8JsonWriter writer, ResponseError value, JsonSerializerOptions options)
        {
            writer.WriteStartObject();
            if (value.Code != null)
            {
                writer.WriteString("code", value.Code);
            }
            if (value.Message != null)
            {
                writer.WriteString("message", value.Message);
            }
            if (value.Target != null)
            {
                writer.WriteString("target", value.Target);
            }
            if (value.Details != null && value.Details.Count > 0)
            {
                writer.WriteStartArray("details");
                foreach (var detail in value.Details)
                {
                    JsonSerializer.Serialize(writer, detail, ResourceManagerJsonSerializerContext.Default.ResponseError);
                }
                writer.WriteEndArray();
            }
            writer.WriteEndObject();
        }
    }
}

